// Obtener el contenido bruto del JSON
const rawOutput = items[0].json.output;

// Limpiar string si contiene etiquetas tipo markdown
const cleanJsonString = rawOutput.replace(/```?json\n?|```|\njson\n?/g, '').trim();

// Parsear JSON
const parsed = JSON.parse(cleanJsonString);

// Normalizar el correo: minúsculas, sin espacios, sin tildes
const correoOriginal = parsed.correo_contacto || '';
const correoNormalizado = correoOriginal
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // quitar tildes
  .replace(/\s+/g, '')                              // quitar espacios
  .toLowerCase();                                   // minúsculas

// Retornar cada campo individual
return [
  {
    json: {
       persona_encargada: parsed.persona_encargada,
      nombre_encargado: parsed.nombre_encargado,
      nombre_empresa: parsed.nombre_empresa,
      rubro_empresa: parsed.rubro_empresa,
      cantidad_empleados: parsed.cantidad_empleados,
      cargo_contacto: parsed.cargo_contacto,
      tiene_lineas_moviles: parsed.tiene_lineas_moviles,
      operador_actual: parsed.operador_actual,
      lineas_necesarias: parsed.lineas_necesarias,
      uso_lineas: parsed.uso_lineas,
      preferencia_datos: parsed.preferencia_datos,
      requiere_equipos: parsed.requiere_equipos,
      tiene_internet_fijo: parsed.tiene_internet_fijo,
      proveedor_internet: parsed.proveedor_internet,
      velocidad_requerida: parsed.velocidad_requerida,
      presupuesto_mensual: parsed.presupuesto_mensual,
      tiempo_contratacion: parsed.tiempo_contratacion,
      nombre_contacto: parsed.nombre_contacto,
      correo_contacto: correoNormalizado,
      telefono_contacto: parsed.telefono_contacto,
      interes: parsed.interes,
      sentimiento: parsed.sentimiento
    }
  }
];
